Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String dummyLine = scanner.nextLine();
        String inputLine = scanner.nextLine();

        int maxLength = 0;
        int totalTokens = 0;
        int position = 0;
        int lastPosition = 0;

        while (position < inputLine.lastIndexOf(')')) {
            int startIdx = inputLine.indexOf('(', position);
            int endIdx = inputLine.indexOf(')', startIdx);
            String segment = inputLine.substring(lastPosition, startIdx);
            StringTokenizer tokenizer = new StringTokenizer(segment, "_");
            while (tokenizer.hasMoreTokens()) {
                int length = tokenizer.nextToken().length();
                if (length > maxLength) maxLength = length;
            }
            String insideContent = inputLine.substring(startIdx + 1, endIdx);
            StringTokenizer innerTokenizer = new StringTokenizer(insideContent, "_");
            while (innerTokenizer.hasMoreTokens()) {
                String token = innerTokenizer.nextToken();
                if (!token.isEmpty()) totalTokens++;
            }
            lastPosition = endIdx + 1;
            position = endIdx;
        }

        String remainingPart = inputLine.substring(lastPosition);
        StringTokenizer remainingTokenizer = new StringTokenizer(remainingPart, "_");
        while (remainingTokenizer.hasMoreTokens()) {
            int length = remainingTokenizer.nextToken().length();
            if (length > maxLength) maxLength = length;
        }

        System.out.println(maxLength + " " + totalTokens);
    }
}
